function loop(now){if(!running)return;const dt=Math.min(.034,(now-last)/1000||0);last=now;update(dt);drawWorld(now/1000);requestAnimationFrame(loop)}
function pointerMove(e){const r=canvas.getBoundingClientRect();aim={x:e.clientX-r.left,y:e.clientY-r.top};const c=document.querySelector('#crosshair');c.style.left=e.clientX+'px';c.style.top=e.clientY+'px'}canvas.addEventListener('pointermove',pointerMove);canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'){canvas.setPointerCapture(e.pointerId);fireHeld=true}});window.addEventListener('pointerup',e=>{if(e.pointerType==='mouse')fireHeld=false});
