const pad=document.querySelector('#movePad'),stick=document.querySelector('#stick');let padPointer=null;pad.addEventListener('pointerdown',e=>{padPointer=e.pointerId;pad.setPointerCapture(e.pointerId);moveStick(e)});pad.addEventListener('pointermove',e=>{if(e.pointerId===padPointer)moveStick(e)});function moveStick(e){const r=pad.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,lim=39,d=Math.hypot(dx,dy)||1,m=Math.min(lim,d);joystick.x=dx/d*m/lim;joystick.y=dy/d*m/lim;stick.style.transform=`translate(${joystick.x*lim}px,${joystick.y*lim}px)`;if(Math.hypot(joystick.x,joystick.y)>.25){player.angle=Math.atan2(joystick.y,joystick.x);touchAim=true}}function resetStick(e){if(e.pointerId!==padPointer)return;padPointer=null;joystick.x=joystick.y=0;stick.style.transform=''}pad.addEventListener('pointerup',resetStick);pad.addEventListener('pointercancel',resetStick);
const fireBtn=document.querySelector('#fireBtn');fireBtn.addEventListener('pointerdown',e=>{e.preventDefault();fireBtn.setPointerCapture(e.pointerId);fireHeld=true;fire()});fireBtn.addEventListener('pointerup',()=>fireHeld=false);fireBtn.addEventListener('pointercancel',()=>fireHeld=false);document.querySelector('#reloadBtn').addEventListener('pointerdown',e=>{e.preventDefault();reload()});
// Dragging on the right half of touch screen aims; fire button stays independent.
canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'){touchAim=true;const r=canvas.getBoundingClientRect();player.angle=Math.atan2(e.clientY-r.top-H/2,e.clientX-r.left-W/2)}});canvas.addEventListener('pointermove',e=>{if(e.pointerType==='touch'&&e.clientX>innerWidth*.42){const r=canvas.getBoundingClientRect();player.angle=Math.atan2(e.clientY-r.top-H/2,e.clientX-r.left-W/2)}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&running)fireHeld=false});
})();
</script></body></html>

